#!/usr/bin/env python3
"""Render a blog Markdown file (YAML-ish front matter + Markdown with inline HTML) to a standalone HTML page.

Usage: python3 render.py eks-hybrid-nodes-demos.md   # writes eks-hybrid-nodes-demos.html next to it
The HTML is generated output: edit the .md and re-run.
"""
import html
import re
import sys
from pathlib import Path

import markdown

TEMPLATE = """<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <!-- generated by blog/render.py from {src}; do not edit -->
  <title>{title}</title>
  <meta name="description" content="{description}">{canonical}
  <link rel="stylesheet" href="../common/theme.css">
  <style>
    html, body {{ overflow: auto; height: auto; }}
    body {{ background: var(--bg-primary, #0f1b2a); color: var(--text-primary, #e8eef5); font-family: var(--font-body, system-ui, sans-serif); line-height: 1.75; }}
    .wrap {{ box-sizing: border-box; width: min(920px, 100%); max-width: 100%; margin: 0 auto; padding: 2.5rem 1.5rem 5rem; }}
    img, video {{ max-width: 100%; }}
    .crumbs {{ font-size: .9rem; margin-bottom: 1.4rem; }}
    .crumbs a {{ color: var(--accent, #3b82f6); text-decoration: none; margin-right: .9rem; }}
    .date {{ color: var(--text-secondary, #9fb0c3); font-size: .9rem; margin: 0 0 1.2rem; }}
    h1 {{ font-size: 2.1rem; line-height: 1.3; margin: 0 0 .4rem; }}
    h2 {{ font-size: 1.5rem; margin: 3rem 0 .9rem; padding-top: 1.1rem; border-top: 1px solid var(--border, #2a3a4d); }}
    h3 {{ font-size: 1.15rem; margin: 1.8rem 0 .5rem; color: var(--accent, #3b82f6); }}
    p, li {{ font-size: 1.02rem; }}
    a {{ color: var(--accent, #3b82f6); }}
    .lead {{ color: var(--text-secondary, #9fb0c3); font-size: 1.08rem; margin: 0 0 1.4rem; }}
    .toc {{ background: var(--bg-card, #16212f); border: 1px solid var(--border, #2a3a4d); border-radius: .5rem; padding: .6rem 1.4rem; margin: 1.4rem 0; }}
    .toc ol {{ margin: .3rem 0 .6rem; }}
    .toc a {{ text-decoration: none; }}
    .callout {{ border-left: 4px solid var(--accent, #3b82f6); background: var(--bg-card, #16212f); padding: .8rem 1rem; margin: 1.2rem 0; border-radius: 0 .4rem .4rem 0; }}
    .callout.warn {{ border-color: var(--warning, #f59e0b); }}
    .callout.bad {{ border-color: var(--danger, #ef4444); }}
    .callout > strong:first-child {{ display: block; margin-bottom: .25rem; }}
    article ul, article ol {{ padding-left: 1.6rem; }}
    article li {{ margin: .25rem 0; }}
    figure.video {{ margin: 1.2rem 0 1.6rem; }}
    figure.video video {{ display: block; width: 100%; aspect-ratio: 16 / 9; background: #000; border-radius: .5rem; border: 1px solid var(--border, #2a3a4d); }}
    figure.video figcaption {{ color: var(--text-secondary, #9fb0c3); font-size: .9rem; margin-top: .4rem; text-align: center; }}
    table {{ width: 100%; border-collapse: collapse; margin: .9rem 0 1.3rem; font-size: .95rem; display: block; overflow-x: auto; }}
    th, td {{ border: 1px solid var(--border, #2a3a4d); padding: .5rem .65rem; text-align: left; vertical-align: top; }}
    th {{ background: var(--bg-card, #16212f); white-space: nowrap; }}
    code, pre {{ font-family: var(--font-mono, ui-monospace, monospace); font-size: .88rem; }}
    code {{ background: rgba(127,127,127,.18); padding: .08rem .3rem; border-radius: .25rem; overflow-wrap: anywhere; }}
    pre {{ background: #0b1522; color: #d7e3f0; padding: .9rem 1rem; border-radius: .4rem; overflow-x: auto; border: 1px solid var(--border, #2a3a4d); }}
    pre code {{ background: none; padding: 0; }}
    .refs {{ margin-top: 2.4rem; }}
  </style>
  <script async src="https://www.googletagmanager.com/gtag/js?id=G-GWVLEW5JLL"></script>
  <script>window.dataLayer=window.dataLayer||[];function gtag(){{dataLayer.push(arguments)}}gtag('js',new Date());gtag('config','G-GWVLEW5JLL');</script>
</head>
<body class="theme-dark">
<article class="wrap">
  <div class="crumbs"><a href="../toc.html">Deep Dive 목차</a><a href="../05-live-demo.html">5부 라이브 데모</a><a href="../demo-guide.html">데모 구현 가이드</a>{blog_link}</div>
  <p class="date">{date}</p>
{body}
</article>
<script>
// Only one demo video plays at a time.
document.querySelectorAll('video').forEach(function (v) {{
  v.addEventListener('play', function () {{
    document.querySelectorAll('video').forEach(function (o) {{ if (o !== v && !o.paused) o.pause(); }});
  }});
}});
</script>
</body>
</html>
"""


def main(src: Path) -> None:
    text = src.read_text(encoding="utf-8")
    meta = {}
    m = re.match(r"^---\n(.*?)\n---\n", text, re.S)
    if m:
        for line in m.group(1).splitlines():
            k, _, v = line.partition(":")
            meta[k.strip()] = v.strip().strip('"')
        text = text[m.end():]
    # md_in_html parses Markdown inside blocks marked markdown="1" (the table of contents).
    body = markdown.markdown(text, extensions=["tables", "fenced_code", "md_in_html"], output_format="html5")
    out = src.with_suffix(".html")
    # canonical: the same post also lives on blog.atomai.click; search engines index that copy.
    canon = meta.get("canonical", "")
    canonical = f'\n  <link rel="canonical" href="{html.escape(canon)}">' if canon else ""
    blog_link = f'<a href="{html.escape(canon)}">블로그에서 보기</a>' if canon else ""
    out.write_text(TEMPLATE.format(
        canonical=canonical, blog_link=blog_link,
        src=src.name, title=html.escape(meta.get("title", src.stem)),
        description=html.escape(meta.get("description", "")), date=html.escape(meta.get("date", "")),
        body=body), encoding="utf-8")
    print(f"wrote {out}")


if __name__ == "__main__":
    main(Path(sys.argv[1]).resolve())
